package net.officefloor.hq.app.invoices;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** A payment received from a client on a date, allocated to its invoices. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id")
    private Long clientId;

    private BigDecimal amount;

    @Column(name = "payment_date")
    private LocalDate date;

    /** The payment reference the client quoted, or null when none was. */
    private String reference;

    @ElementCollection
    @CollectionTable(name = "payment_allocation", joinColumns = @JoinColumn(name = "payment_id"))
    private List<PaymentAllocation> allocations = new ArrayList<>();

    protected Payment() {
    }

    /** A payment made wholly against one invoice, quoting the reference (null when none). */
    public static Payment against(Invoice invoice, BigDecimal amount, LocalDate date, String reference) {
        Payment payment = new Payment();
        payment.clientId = invoice.getClientId();
        payment.amount = amount;
        payment.date = date;
        payment.reference = reference;
        payment.allocations.add(new PaymentAllocation(invoice.getId(), amount));
        return payment;
    }

    /**
     * A payment from the client spread over several of its invoices, quoting the reference (null when
     * none): each allocation is the part of the amount that goes to one invoice.
     */
    public static Payment split(Long clientId, BigDecimal amount, LocalDate date, String reference,
            List<PaymentAllocation> allocations) {
        Payment payment = new Payment();
        payment.clientId = clientId;
        payment.amount = amount;
        payment.date = date;
        payment.reference = reference;
        payment.allocations.addAll(allocations);
        return payment;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getReference() {
        return reference;
    }

    public List<PaymentAllocation> getAllocations() {
        return allocations;
    }

    /** How much of this payment goes to the invoice. */
    public BigDecimal amountTo(Long invoiceId) {
        return allocations.stream().filter(a -> a.getInvoiceId().equals(invoiceId))
                .map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
package net.officefloor.hq.app.invoices;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;

/** The part of a payment that goes to one invoice. */
@Embeddable
public class PaymentAllocation {

    @Column(name = "invoice_id")
    private Long invoiceId;

    private BigDecimal amount;

    protected PaymentAllocation() {
    }

    public PaymentAllocation(Long invoiceId, BigDecimal amount) {
        this.invoiceId = invoiceId;
        this.amount = amount;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public BigDecimal getAmount() {
        return amount;
    }
}
package net.officefloor.hq.app.invoices;

import java.util.Collection;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** The payments with a part allocated to the invoice, oldest first. */
    @Query("SELECT DISTINCT p FROM Payment p LEFT JOIN FETCH p.allocations WHERE p.id IN (SELECT q.id FROM Payment q JOIN q.allocations a WHERE a.invoiceId = :invoiceId) ORDER BY p.date, p.id")
    List<Payment> findForInvoice(@Param("invoiceId") Long invoiceId);

    /** For each of the invoices that has been paid something, its id and the amount paid to it. */
    @Query("SELECT a.invoiceId, SUM(a.amount) FROM Payment p JOIN p.allocations a WHERE a.invoiceId IN :invoiceIds GROUP BY a.invoiceId")
    List<Object[]> paidTo(@Param("invoiceIds") Collection<Long> invoiceIds);
}
package net.officefloor.hq.app.invoices;

import jakarta.validation.Valid;
import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.IntStream;
import net.officefloor.hq.app.TaxRate;
import net.officefloor.hq.app.Today;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
public class InvoiceController {

    /**
     * An invoice as listed: its total is a decimal string to the cent, e.g. "25.25"; its status
     * follows what has been paid and whether it is past due.
     */
    public record InvoiceSummary(Long id, String number, InvoiceStatus status, String total,
            LocalDate issueDate, LocalDate dueDate) {
        static InvoiceSummary of(Invoice i, BigDecimal taxRate, BigDecimal paid, LocalDate today) {
            BigDecimal total = i.total(taxRate);
            return new InvoiceSummary(i.getId(), InvoiceNumber.of(i.getId()), i.statusWhenPaid(paid, taxRate, today),
                    total.toPlainString(), i.getIssueDate(), i.getDueDate());
        }
    }

    /**
     * What a client still owes across its sent invoices (drafts do not count), after discounts, tax
     * and payments, and how much of that is overdue; decimal strings to the cent.
     */
    public record ClientBalance(Long clientId, String balance, String overdue) {
    }

    /**
     * A payment made to an opened invoice: the whole amount paid and how much of it went to this
     * invoice (to the cent), its date and the reference it quoted in groups of four (null when none).
     */
    public record PaymentView(Long id, String amount, String allocated, LocalDate date, String reference) {
        static PaymentView of(Payment p, Long invoiceId) {
            return new PaymentView(p.getId(), p.getAmount().setScale(2).toPlainString(),
                    p.amountTo(invoiceId).setScale(2).toPlainString(), p.getDate(),
                    p.getReference() == null ? null : PaymentReference.grouped(p.getReference()));
        }
    }

    /**
     * One line of an opened invoice. The quantity is as entered, without trailing zeros ("1.5");
     * money is a decimal string to the cent. {@code discountShare} is the line's share of the
     * invoice discount; {@code tax} is the line's tax, the rate on its amount less that share, and
     * {@code taxExempt} lines have none. {@code discountPct}
     * (without trailing zeros) is the line's own discount and {@code discount} what it takes off;
     * {@code amount} is after it.
     */
    public record LineView(Long id, String description, String qty, String unitPrice, String discountPct,
            String discount, String amount, String discountShare, String tax, boolean taxExempt) {
        static LineView of(InvoiceLine l, BigDecimal discountShare, BigDecimal tax) {
            return new LineView(l.getId(), l.getDescription(), l.getQty().stripTrailingZeros().toPlainString(),
                    l.getUnitPrice().setScale(2).toPlainString(),
                    l.getDiscountPct().stripTrailingZeros().toPlainString(), l.discount().toPlainString(),
                    l.amount().toPlainString(), discountShare.toPlainString(), tax.toPlainString(),
                    l.isTaxExempt());
        }
    }

    /**
     * An opened invoice: its lines, subtotal, discount percentage (without trailing zeros, "12.5"),
     * the amount it takes off, the tax rate (without trailing zeros) and the tax charged, the sum of the
     * line taxes, and the grand total; the payments made to it, what they add up to and what is still due (money as
     * decimal strings to the cent). Its status follows what has been paid. {@code reference} is its
     * RF payment reference in groups of four.
     */
    public record InvoiceDetail(Long id, String number, String reference, Long clientId, InvoiceStatus status, LocalDate issueDate,
            LocalDate dueDate, List<LineView> lines, String subtotal, String discountPct, String discountAmount,
            String discountCap, String discount, String taxRate, String tax, String total, List<PaymentView> payments, String paid, String amountDue) {
        static InvoiceDetail of(Invoice i, BigDecimal taxRate, List<Payment> payments, LocalDate today) {
            BigDecimal paid = payments.stream().map(p -> p.amountTo(i.getId()))
                    .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
            List<BigDecimal> shares = i.discountShares();
            List<BigDecimal> taxes = i.lineTaxes(taxRate);
            List<LineView> lines = IntStream.range(0, shares.size())
                    .mapToObj(n -> LineView.of(i.getLines().get(n), shares.get(n), taxes.get(n))).toList();
            return new InvoiceDetail(i.getId(), InvoiceNumber.of(i.getId()),
                    PaymentReference.grouped(PaymentReference.of(i.getId())), i.getClientId(),
                    i.statusWhenPaid(paid, taxRate, today), i.getIssueDate(), i.getDueDate(),
                    lines, i.subtotal().toPlainString(),
                    i.getDiscountPct().stripTrailingZeros().toPlainString(),
                    i.getDiscountAmount().setScale(2).toPlainString(),
                    i.getDiscountCap() == null ? null : i.getDiscountCap().setScale(2).toPlainString(),
                    i.discount().toPlainString(),
                    taxRate.stripTrailingZeros().toPlainString(), i.tax(taxRate).toPlainString(),
                    i.total(taxRate).toPlainString(),
                    payments.stream().map(p -> PaymentView.of(p, i.getId())).toList(), paid.toPlainString(),
                    i.amountDue(paid, taxRate).toPlainString());
        }
    }

    /**
     * A discount to give: a percentage from 0 to 100 with at most two decimals, or a fixed amount
     * of money, not negative and to the cent. Exactly one of them. Optionally a cap, money not
     * negative and to the cent, that a percentage never takes off more than.
     */
    public record NewDiscount(
            @DecimalMin(value = "0", message = "The discount must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The discount must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The discount can have at most two decimals.")
            BigDecimal discountPct,
            @DecimalMin(value = "0", message = "The discount amount cannot be negative.")
            @Digits(integer = 10, fraction = 2, message = "The discount amount can have at most two decimals.")
            BigDecimal discountAmount,
            @DecimalMin(value = "0", message = "The discount cap cannot be negative.")
            @Digits(integer = 10, fraction = 2, message = "The discount cap can have at most two decimals.")
            BigDecimal discountCap) {

        @AssertTrue(message = "Enter either a discount percentage or a discount amount.")
        public boolean isDiscountGiven() {
            return (discountPct == null) != (discountAmount == null);
        }
    }

    /**
     * A line to add: a description, a quantity above zero and a unit price of at least $0.01, and
     * whether it is tax exempt (taxable when left out), and its own discount percentage from 0 to 100
     * with at most two decimals (none when left out).
     */
    public record NewLine(
            @NotBlank(message = "Enter a description.")
            @Size(max = 255, message = "The description must be at most 255 characters.")
            String description,
            @NotNull(message = "Enter a quantity.")
            @DecimalMin(value = "0", inclusive = false, message = "The quantity must be more than zero.")
            @Digits(integer = 10, fraction = 2, message = "The quantity can have at most two decimals.")
            BigDecimal qty,
            @NotNull(message = "Enter a unit price.")
            @DecimalMin(value = "0.01", message = "The unit price must be at least $0.01.")
            @Digits(integer = 17, fraction = 2, message = "The unit price can have at most two decimals.")
            BigDecimal unitPrice,
            Boolean taxExempt,
            @DecimalMin(value = "0", message = "The line discount must be from 0 to 100 percent.")
            @DecimalMax(value = "100", message = "The line discount must be from 0 to 100 percent.")
            @Digits(integer = 3, fraction = 2, message = "The line discount can have at most two decimals.")
            BigDecimal discountPct) {
    }

    /**
     * A payment to record: an amount more than zero with at most two decimals, the date it was paid,
     * and the reference the client quoted (optional).
     */
    public record NewPayment(
            @NotNull(message = "Enter an amount.")
            @DecimalMin(value = "0", inclusive = false, message = "The amount must be more than zero.")
            @Digits(integer = 17, fraction = 2, message = "The amount can have at most two decimals.")
            BigDecimal amount,
            @NotNull(message = "Enter the date it was paid.")
            LocalDate date,
            @Size(max = 64, message = "The reference must be at most 64 characters.")
            String reference) {
    }

    /** The part of a split payment that goes to one invoice: more than zero, with at most two decimals. */
    public record NewAllocation(
            @NotNull(message = "Choose the invoice each part of the payment goes to.")
            Long invoiceId,
            @NotNull(message = "Enter how much of the payment goes to each invoice.")
            @DecimalMin(value = "0", inclusive = false, message = "Each invoice's part must be more than zero.")
            @Digits(integer = 17, fraction = 2, message = "Each invoice's part can have at most two decimals.")
            BigDecimal amount) {
    }

    /** A payment to spread over several of a client's invoices: a payment and the part going to each. */
    public record NewSplitPayment(
            @NotNull(message = "Enter an amount.")
            @DecimalMin(value = "0", inclusive = false, message = "The amount must be more than zero.")
            @Digits(integer = 17, fraction = 2, message = "The amount can have at most two decimals.")
            BigDecimal amount,
            @NotNull(message = "Enter the date it was paid.")
            LocalDate date,
            @Size(max = 64, message = "The reference must be at most 64 characters.")
            String reference,
            @NotNull(message = "Enter how much of the payment goes to each invoice.")
            List<@Valid NewAllocation> allocations) {
    }

    private final InvoiceService invoices;
    private final TaxRate taxRate;
    private final Today today;

    public InvoiceController(InvoiceService invoices, TaxRate taxRate, Today today) {
        this.invoices = invoices;
        this.taxRate = taxRate;
        this.today = today;
    }

    private InvoiceSummary summary(Invoice i) {
        return InvoiceSummary.of(i, taxRate.percent(), invoices.paid(List.of(i)).get(i.getId()), today.date());
    }

    private InvoiceDetail detail(Invoice i) {
        return InvoiceDetail.of(i, taxRate.percent(), invoices.payments(i.getId()), today.date());
    }

    @GetMapping("/api/clients/{clientId}/invoices")
    public List<InvoiceSummary> forClient(@PathVariable Long clientId) {
        BigDecimal rate = taxRate.percent();
        List<Invoice> list = invoices.forClient(clientId);
        Map<Long, BigDecimal> paid = invoices.paid(list);
        LocalDate on = today.date();
        return list.stream().map(i -> InvoiceSummary.of(i, rate, paid.get(i.getId()), on)).toList();
    }

    /** The balance of each client that has a sent invoice; a client not listed owes nothing. Void invoices do not count. */
    @GetMapping("/api/clients/balances")
    public List<ClientBalance> balances() {
        BigDecimal rate = taxRate.percent();
        List<Invoice> sent = invoices.all().stream().filter(i -> !i.isDraft() && !i.isVoid()).toList();
        Map<Long, BigDecimal> paid = invoices.paid(sent);
        LocalDate on = today.date();
        Map<Long, BigDecimal[]> owed = new TreeMap<>();
        for (Invoice i : sent) {
            BigDecimal due = i.amountDue(paid.get(i.getId()), rate);
            BigDecimal[] sums = owed.computeIfAbsent(i.getClientId(),
                    k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
            sums[0] = sums[0].add(due);
            if (i.statusWhenPaid(paid.get(i.getId()), rate, on) == InvoiceStatus.OVERDUE) {
                sums[1] = sums[1].add(due);
            }
        }
        return owed.entrySet().stream().map(e -> new ClientBalance(e.getKey(),
                e.getValue()[0].toPlainString(), e.getValue()[1].toPlainString())).toList();
    }

    @PostMapping("/api/clients/{clientId}/invoices")
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceSummary newDraft(@PathVariable Long clientId) {
        return invoices.newDraft(clientId).map(this::summary)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such client."));
    }

    @GetMapping("/api/invoices/{id}")
    public InvoiceDetail open(@PathVariable Long id) {
        return invoices.find(id).map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }

    /** Opens the invoice with a typed number; a number whose check digit is wrong is refused. */
    @GetMapping("/api/invoices/by-number/{number}")
    public InvoiceDetail openByNumber(@PathVariable String number) {
        Long id = InvoiceNumber.idOf(number).orElseThrow(() -> new ResponseStatusException(
                HttpStatus.BAD_REQUEST, number.trim() + " is mistyped: check the invoice number."));
        return invoices.find(id).map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,
                        "There is no invoice " + number.trim() + "."));
    }

    @PostMapping("/api/invoices/{id}/lines")
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceDetail addLine(@PathVariable Long id, @Valid @RequestBody NewLine body) {
        return invoices.addLine(id, body.description().trim(), body.qty(), body.unitPrice(),
                Boolean.TRUE.equals(body.taxExempt()),
                body.discountPct() == null ? BigDecimal.ZERO : body.discountPct())
                .map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }

    @PutMapping("/api/invoices/{id}/discount")
    public InvoiceDetail setDiscount(@PathVariable Long id, @Valid @RequestBody NewDiscount body) {
        return invoices.setDiscount(id, body.discountPct(), body.discountAmount(), body.discountCap())
                .map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }

    @PostMapping("/api/invoices/{id}/send")
    public InvoiceDetail send(@PathVariable Long id) {
        return invoices.send(id)
                .map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }

    @PostMapping("/api/invoices/{id}/void")
    public InvoiceDetail voidInvoice(@PathVariable Long id) {
        return invoices.voidInvoice(id)
                .map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }

    /**
     * Records one payment spread over several of the client's invoices, or, with no parts given,
     * applied to its oldest unpaid invoices first; answers the client's invoices
     * with their new statuses.
     */
    @PostMapping("/api/clients/{clientId}/payments")
    @ResponseStatus(HttpStatus.CREATED)
    public List<InvoiceSummary> recordSplitPayment(@PathVariable Long clientId, @Valid @RequestBody NewSplitPayment body) {
        if (body.allocations().isEmpty()) {
            invoices.recordAutoPayment(clientId, body.amount(), body.date(), reference(body.reference()));
        } else {
            invoices.recordSplitPayment(clientId, body.amount(), body.date(), reference(body.reference()),
                    body.allocations().stream().map(a -> new PaymentAllocation(a.invoiceId(), a.amount())).toList());
        }
        return forClient(clientId);
    }

    /** The quoted reference without spaces, or null when none was; a mistyped one is refused. */
    private static String reference(String typed) {
        if (typed == null || typed.isBlank()) {
            return null;
        }
        return PaymentReference.parse(typed).orElseThrow(() -> new ResponseStatusException(
                HttpStatus.BAD_REQUEST, typed.trim() + " is mistyped: check the payment reference."));
    }

    @PostMapping("/api/invoices/{id}/payments")
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceDetail recordPayment(@PathVariable Long id, @Valid @RequestBody NewPayment body) {
        return invoices.recordPayment(id, body.amount(), body.date(), reference(body.reference()))
                .map(this::detail)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such invoice."));
    }
}
package net.officefloor.hq.app.invoices;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.TaxRate;
import net.officefloor.hq.app.Today;
import net.officefloor.hq.app.clients.ClientRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Lists a client's invoices, opens one, starts new drafts, adds lines to them, gives them a discount,
 * sends them, voids them and records payments against them.
 */
@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final Today today;
    private final TaxRate taxRate;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, PaymentRepository payments, ClientRepository clients,
            Today today, TaxRate taxRate, Audit audit) {
        this.invoices = invoices;
        this.payments = payments;
        this.clients = clients;
        this.today = today;
        this.taxRate = taxRate;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Invoice> forClient(Long clientId) {
        return invoices.findByClientIdOrderByIdAsc(clientId);
    }

    /** Every invoice of every client, with its lines. */
    @Transactional(readOnly = true)
    public List<Invoice> all() {
        return invoices.findAllByOrderByIdAsc();
    }

    @Transactional(readOnly = true)
    public Optional<Invoice> find(Long id) {
        return invoices.findWithLinesById(id);
    }

    /** An empty draft for the client, issued today and due on the last day of the following month; empty if no such client. */
    @Transactional
    public Optional<Invoice> newDraft(Long clientId) {
        if (!clients.existsById(clientId)) {
            return Optional.empty();
        }
        LocalDate issued = today.date();
        return Optional.of(invoices.save(Invoice.draft(clientId, issued, dueDateFor(issued))));
    }

    /** A new invoice is due on the last day of the month after the month it is issued in. */
    static LocalDate dueDateFor(LocalDate issued) {
        LocalDate nextMonth = issued.plusMonths(1);
        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
    }

    /**
     * Adds a line to an invoice; empty if no such invoice. The line has already been checked. A sent
     * invoice with no payments goes back to draft; one with a payment refuses it.
     */
    @Transactional
    public Optional<Invoice> addLine(Long invoiceId, String description, BigDecimal qty, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot take new lines.");
            invoice.addLine(new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct));
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Gives an invoice a percentage discount, or a fixed amount off when one is given; the one given
     * clears the other, and the cap (null for none) limits a percentage. Empty if no such invoice. The values have already been checked; a fixed amount
     * over the subtotal is refused. A sent invoice with no payments goes back to draft; one with a
     * payment refuses it.
     */
    @Transactional
    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
            BigDecimal discountCap) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
            if (discountAmount != null) {
                invoice.setDiscountAmount(discountAmount);
            } else {
                invoice.setDiscountPct(discountPct);
            }
            invoice.setDiscountCap(discountCap);
            invoices.saveAndFlush(invoice);
            if (reopened) {
                audit.record("INVOICE_REOPENED id=" + invoice.getId());
            }
        });
        return found;
    }

    /**
     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
     * back to draft, to be sent again; an invoice with any payment is refused with the message.
     * Whether it went back to draft.
     */
    private boolean reopenForChange(Invoice invoice, String refusal) {
        if (invoice.isDraft()) {
            return false;
        }
        if (invoice.isVoid()) {
            throw new InvoiceRejectedException("A void invoice cannot be changed.");
        }
        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
            throw new InvoiceRejectedException(refusal);
        }
        invoice.reopen();
        return true;
    }

    /**
     * Sends a draft invoice, issuing it today and making it due on the last day of the following
     * month, and records it in the audit; empty if
     * no such invoice. An invoice already sent, or with no lines, is refused.
     */
    @Transactional
    public Optional<Invoice> send(Long invoiceId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("A void invoice cannot be sent.");
            }
            if (!invoice.isDraft()) {
                throw new InvoiceRejectedException("This invoice has already been sent.");
            }
            if (invoice.getLines().isEmpty()) {
                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
            }
            LocalDate issued = today.date();
            invoice.markSent(issued, dueDateFor(issued));
            invoices.saveAndFlush(invoice);
            audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + InvoiceNumber.of(invoice.getId())
                    + " total=" + invoice.total(taxRate.percent()).toPlainString());
        });
        return found;
    }

    /**
     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
     * draft, an invoice already void, or one with any payment is refused.
     */
    @Transactional
    public Optional<Invoice> voidInvoice(Long invoiceId) {
        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
        found.ifPresent(invoice -> {
            if (invoice.isVoid()) {
                throw new InvoiceRejectedException("This invoice is already void.");
            }

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.context.annotation.Profile;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private static final Set<String> FIXTURE_KEYS = Set.of("asOf", "settings", "clients", "invoices", "payments");
    private static final Set<String> SETTINGS_FIELDS = Set.of("taxRate");
    private static final Set<String> CLIENT_FIELDS = Set.of("id", "name", "email");
    private static final Set<String> INVOICE_FIELDS =
            Set.of("id", "clientId", "status", "issueDate", "dueDate", "discountPct", "discountAmount", "discountCap", "lineItems");
    private static final Set<String> LINE_FIELDS = Set.of("id", "description", "qty", "unitPrice", "taxExempt", "discountPct");
    private static final Set<String> PAYMENT_FIELDS = Set.of("id", "clientId", "amount", "date", "reference", "allocations");
    private static final Set<String> ALLOCATION_FIELDS = Set.of("invoiceId", "amount");
    private static final Set<String> STATUSES = Set.of("DRAFT", "SENT", "VOID");

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        jdbc.execute("DELETE FROM app_setting");
        jdbc.execute("DELETE FROM payment_allocation");
        for (String table : List.of("payment", "invoice_line", "invoice", "client")) {
            jdbc.execute("DELETE FROM " + table);
            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH 1");
        }
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
     */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (String key : fixture.keySet()) {
            if (!FIXTURE_KEYS.contains(key)) {
                throw refuse("unsupported fixture key: " + key);
            }
        }
        if (fixture.get("asOf") != null) {
            LocalDate asOf = date(fixture.get("asOf"), "asOf");
            jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", Today.AS_OF, asOf.toString());
        }
        if (fixture.get("settings") != null) {
            if (!(fixture.get("settings") instanceof Map<?, ?> settings)) {
                throw refuse("settings must be an object");
            }
            @SuppressWarnings("unchecked")
            Map<String, Object> values = (Map<String, Object>) settings;
            only(values, SETTINGS_FIELDS, "settings");
            if (values.get("taxRate") != null) {
                BigDecimal rate = percent(values.get("taxRate"), "settings.taxRate");
                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", TaxRate.TAX_RATE,
                        rate.toPlainString());
            }
        }
        for (Map<String, Object> row : rows(fixture.get("clients"), "clients")) {
            only(row, CLIENT_FIELDS, "clients[]");
            Object id = row.get("id");
            if (id == null) {
                jdbc.update("INSERT INTO client (name, email) VALUES (?, ?)",
                        text(row, "name"), text(row, "email"));
            } else {
                jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
                        id(id), text(row, "name"), text(row, "email"));
            }
        }
        for (Map<String, Object> row : rows(fixture.get("invoices"), "invoices")) {
            only(row, INVOICE_FIELDS, "invoices[]");
            String status = row.get("status") == null ? "DRAFT" : row.get("status").toString();
            if (!STATUSES.contains(status)) {
                throw refuse("unsupported value of invoices[].status: " + status);
            }
            if (row.get("clientId") == null) {
                throw refuse("invoices[].clientId is required");
            }
            Long invoiceId = insert("invoice", row.get("id"),
                    new String[] {"client_id", "status", "issue_date", "due_date", "discount_pct", "discount_amount", "discount_cap"},
                    id(row.get("clientId")), status,
                    row.get("issueDate") == null ? null : date(row.get("issueDate"), "invoices[].issueDate"),
                    row.get("dueDate") == null ? null : date(row.get("dueDate"), "invoices[].dueDate"),
                    percent(row.get("discountPct"), "invoices[].discountPct"),
                    money(row.get("discountAmount"), "invoices[].discountAmount"),
                    row.get("discountCap") == null ? null : money(row.get("discountCap"), "invoices[].discountCap"));
            for (Map<String, Object> line : rows(row.get("lineItems"), "invoices[].lineItems")) {
                only(line, LINE_FIELDS, "invoices[].lineItems[]");
                insert("invoice_line", line.get("id"),
                        new String[] {"invoice_id", "description", "qty", "unit_price", "tax_exempt", "discount_pct"},
                        invoiceId, text(line, "description"),
                        cents(line.get("qty"), "invoices[].lineItems[].qty"),
                        cents(line.get("unitPrice"), "invoices[].lineItems[].unitPrice"),
                        flag(line.get("taxExempt"), "invoices[].lineItems[].taxExempt"),
                        percent(line.get("discountPct"), "invoices[].lineItems[].discountPct"));
            }
        }
        for (Map<String, Object> row : rows(fixture.get("payments"), "payments")) {
            only(row, PAYMENT_FIELDS, "payments[]");
            if (row.get("clientId") == null) {
                throw refuse("payments[].clientId is required");
            }
            if (row.get("date") == null) {
                throw refuse("payments[].date is required");
            }
            Long paymentId = insert("payment", row.get("id"), new String[] {"client_id", "amount", "payment_date", "reference"},
                    id(row.get("clientId")), cents(row.get("amount"), "payments[].amount"),
                    date(row.get("date"), "payments[].date"),
                    row.get("reference") == null ? null : row.get("reference").toString());
            for (Map<String, Object> allocation : rows(row.get("allocations"), "payments[].allocations")) {
                only(allocation, ALLOCATION_FIELDS, "payments[].allocations[]");
                if (allocation.get("invoiceId") == null) {
                    throw refuse("payments[].allocations[].invoiceId is required");
                }
                jdbc.update("INSERT INTO payment_allocation (payment_id, invoice_id, amount) VALUES (?, ?, ?)",
                        paymentId, id(allocation.get("invoiceId")),
                        cents(allocation.get("amount"), "payments[].allocations[].amount"));
            }
        }
        // Keep generated ids clear of the seeded ones.
        for (String table : List.of("client", "invoice", "invoice_line", "payment")) {
            Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
        }
    }

    /**
     * Read back what is stored, in the same shape and with the same field names the fixtures use,
     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4).
     */
    @GetMapping("/fixture")
    public Map<String, Object> fixture() {
        Map<String, Object> out = new LinkedHashMap<>();
        List<String> asOf = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class,
                Today.AS_OF);
        if (!asOf.isEmpty()) {
            out.put("asOf", asOf.get(0));
        }
        List<String> taxRate = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, TaxRate.TAX_RATE);
        if (!taxRate.isEmpty()) {
            out.put("settings", Map.of("taxRate", new BigDecimal(taxRate.get(0))));
        }
        out.put("clients", jdbc.queryForList("SELECT id, name, email FROM client ORDER BY id").stream()
                .map(r -> {
                    Map<String, Object> row = new LinkedHashMap<>();
                    row.put("id", r.get("ID"));
                    row.put("name", r.get("NAME"));
                    row.put("email", r.get("EMAIL"));
                    return row;
                }).toList());
        out.put("invoices", jdbc.queryForList(
                "SELECT id, client_id, status, issue_date, due_date, discount_pct, discount_amount, discount_cap FROM invoice ORDER BY id").stream()
                .map(r -> {
                    Map<String, Object> row = new LinkedHashMap<>();
                    row.put("id", r.get("ID"));
                    row.put("clientId", r.get("CLIENT_ID"));
                    row.put("status", r.get("STATUS"));
                    row.put("issueDate", r.get("ISSUE_DATE") == null ? null : r.get("ISSUE_DATE").toString());
                    row.put("dueDate", r.get("DUE_DATE") == null ? null : r.get("DUE_DATE").toString());
                    row.put("discountPct", r.get("DISCOUNT_PCT"));
                    row.put("discountAmount", r.get("DISCOUNT_AMOUNT"));
                    if (r.get("DISCOUNT_CAP") != null) {
                        row.put("discountCap", r.get("DISCOUNT_CAP"));
                    }
                    row.put("lineItems", jdbc.queryForList(
                            "SELECT id, description, qty, unit_price, tax_exempt, discount_pct FROM invoice_line WHERE invoice_id = ? ORDER BY id",
                            r.get("ID")).stream().map(l -> {
                                Map<String, Object> line = new LinkedHashMap<>();
                                line.put("id", l.get("ID"));
                                line.put("description", l.get("DESCRIPTION"));
                                line.put("qty", l.get("QTY"));
                                line.put("unitPrice", l.get("UNIT_PRICE"));
                                line.put("taxExempt", l.get("TAX_EXEMPT"));
                                line.put("discountPct", l.get("DISCOUNT_PCT"));
                                return line;
                            }).toList());
                    return row;
                }).toList());
        out.put("payments", jdbc.queryForList("SELECT id, client_id, amount, payment_date, reference FROM payment ORDER BY id")
                .stream().map(r -> {
                    Map<String, Object> row = new LinkedHashMap<>();
                    row.put("id", r.get("ID"));
                    row.put("clientId", r.get("CLIENT_ID"));
                    row.put("amount", r.get("AMOUNT"));
                    row.put("date", r.get("PAYMENT_DATE").toString());
                    row.put("reference", r.get("REFERENCE"));
                    row.put("allocations", jdbc.queryForList(
                            "SELECT invoice_id, amount FROM payment_allocation WHERE payment_id = ? ORDER BY invoice_id",
                            r.get("ID")).stream().map(a -> {
                                Map<String, Object> allocation = new LinkedHashMap<>();
                                allocation.put("invoiceId", a.get("INVOICE_ID"));
                                allocation.put("amount", a.get("AMOUNT"));
                                return allocation;
                            }).toList());
                    return row;
                }).toList());
        return out;
    }

    /** Insert a row with the given id, or a generated one when none is given; returns the id. */
    private Long insert(String table, Object id, String[] columns, Object... values) {
        String cols = String.join(", ", columns);
        String marks = String.join(", ", Collections.nCopies(columns.length, "?"));
        if (id != null) {
            Object[] args = new Object[values.length + 1];
            args[0] = id(id);
            System.arraycopy(values, 0, args, 1, values.length);
            jdbc.update("INSERT INTO " + table + " (id, " + cols + ") VALUES (?, " + marks + ")", args);
            return id(id);
        }
        jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")", values);
        return jdbc.queryForObject("SELECT MAX(id) FROM " + table, Long.class);
    }

    /** A true/false flag; false when left out. */
    private static boolean flag(Object value, String where) {
        if (value == null) {
            return false;
        }
        if (!(value instanceof Boolean b)) {
            throw refuse(where + " must be true or false");
        }
        return b;
    }

    private static void only(Map<String, Object> row, Set<String> fields, String where) {
        for (String field : row.keySet()) {
            if (!fields.contains(field)) {
                throw refuse("unsupported field: " + where + "." + field);
            }
        }
    }

    private static Long id(Object value) {
        if (value instanceof Number n) {
            return n.longValue();
        }
        try {
            return Long.valueOf(value.toString());
        } catch (NumberFormatException e) {
            throw refuse("not an id: " + value);
        }
    }

    private static LocalDate date(Object value, String field) {
        try {
            return LocalDate.parse(value.toString());
        } catch (DateTimeParseException e) {
            throw refuse(field + " must be a yyyy-mm-dd date, not " + value);
        }
    }

    /** A number stored to the cent; refuses a value it could only store by rounding. */
    private static BigDecimal cents(Object value, String field) {
        if (value == null) {
            throw refuse(field + " is required");
        }
        BigDecimal number;
        try {
            number = new BigDecimal(value.toString());
        } catch (NumberFormatException e) {
            throw refuse(field + " must be a number, not " + value);
        }
        if (number.stripTrailingZeros().scale() > 2) {
            throw refuse(field + " can have at most two decimals, not " + value);
        }
        return number;
    }

    /** A percentage from 0 to 100 with at most two decimals; none given is zero. */
    private static BigDecimal percent(Object value, String field) {
        if (value == null) {
            return BigDecimal.ZERO;
        }
        BigDecimal number = cents(value, field);
        if (number.signum() < 0 || number.compareTo(BigDecimal.valueOf(100)) > 0) {
            throw refuse(field + " must be from 0 to 100, not " + value);
        }
        return number;
    }

    /** An optional amount of money, not negative and to the cent; 0 when left out. */
    private static BigDecimal money(Object value, String field) {
        if (value == null) {
            return BigDecimal.ZERO;
        }
        BigDecimal number = cents(value, field);
        if (number.signum() < 0) {
            throw refuse(field + " cannot be negative, not " + value);
        }
        return number;
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> rows(Object value, String key) {
        if (value == null) {
            return List.of();
        }
        if (!(value instanceof List<?> list)) {
            throw refuse(key + " must be a list of rows");
        }
        List<Map<String, Object>> out = new ArrayList<>();
        for (Object o : list) {
            if (!(o instanceof Map<?, ?> m)) {
                throw refuse(key + " must be a list of rows");
            }
            out.add((Map<String, Object>) m);
        }
        return out;
    }

    private static String text(Map<String, Object> row, String field) {
        Object v = row.get(field);
        return v == null ? "" : v.toString();
    }

    private static ResponseStatusException refuse(String message) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
    }
}
